-- Переводы title/summary для новостей, у которых языковые строки
-- остались английскими. Сгенерировано 2026-08-04.
-- Строк: 112. Идемпотентно — UPDATE по slug+lang.

UPDATE news SET title = $t$Amazon Q Developer IDE Plugin será reemplazado por Kiro, un nuevo IDE agéntico basado en especificaciones$t$, summary = $t$AWS bloqueó los nuevos registros del plugin Amazon Q Developer IDE a partir del 15 de mayo de 2026, anunciando su reemplazo: Kiro, un IDE agéntico basado en especificaciones. Kiro utiliza "Specs" (requisitos en lenguaje natural que impulsan la implementación completa) y "Hooks" (activadores automáticos al guardar un archivo o hacer un commit). El soporte del plugin para IDE finaliza el 30 de abril de 2027.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'es';

UPDATE news SET title = $t$Amazon Q Developer IDE-Plugin wird durch Kiro ersetzt – eine neue spec-getriebene agentische IDE$t$, summary = $t$AWS blockierte ab dem 15. Mai 2026 neue Anmeldungen für das Amazon Q Developer IDE-Plugin und kündigte dessen Nachfolger an: Kiro, eine spec-getriebene agentische IDE. Kiro nutzt „Specs“ (Anforderungen in natürlicher Sprache, die die vollständige Implementierung steuern) und „Hooks“ (automatische Auslöser beim Speichern von Dateien oder bei Commits). Der Support für das IDE-Plugin endet am 30. April 2027.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'de';

UPDATE news SET title = $t$Amazon заменяет плагин Q Developer IDE на Kiro — новую agentic-IDE со спецификациями$t$, summary = $t$AWS заблокировала регистрацию новых пользователей плагина Amazon Q Developer IDE с 15 мая 2026 года, объявив о его замене — Kiro, agentic-IDE на основе спецификаций. Kiro использует «Specs» (требования на естественном языке, определяющие полную реализацию) и «Hooks» (автоматические триггеры при сохранении файла или коммите). Поддержка плагина IDE прекратится 30 апреля 2027 года.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'ru';

UPDATE news SET title = $t$Плагін Amazon Q Developer для IDE замінили на Kiro — новий agentic IDE на основі специфікацій$t$, summary = $t$AWS заблокувала нові реєстрації у плагіні Amazon Q Developer для IDE з 15 травня 2026 року, оголосивши про його заміну: Kiro, agentic IDE, що працює на основі специфікацій. Kiro використовує "Specs" (вимоги природною мовою, які визначають повну реалізацію) та "Hooks" (автоматичні тригери при збереженні файлу чи коміті). Підтримка плагіна для IDE завершиться 30 квітня 2027 року.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'ua';

UPDATE news SET title = $t$תוסף ה-IDE של Amazon Q Developer מוחלף ב-Kiro — סביבת פיתוח אג'נטית מבוססת-מפרטים$t$, summary = $t$AWS חסמה הרשמה חדשה לתוסף ה-IDE של Amazon Q Developer מ-15 במאי 2026, והכריזה על התחליף שלו: Kiro, סביבת פיתוח (IDE) אג'נטית מבוססת-מפרטים. Kiro משתמשת ב-"Specs" (דרישות בשפה טבעית שמניבות מימוש מלא) וב-"Hooks" (טריגרים אוטומטיים בעת שמירת קובץ או commit). התמיכה בתוסף ה-IDE תסתיים ב-30 באפריל 2027.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'he';

UPDATE news SET title = $t$Le plugin IDE Amazon Q Developer remplacé par Kiro, un nouvel IDE agentique piloté par spécifications$t$, summary = $t$AWS a bloqué les nouvelles inscriptions au plugin IDE Amazon Q Developer à partir du 15 mai 2026, annonçant son remplaçant : Kiro, un IDE agentique piloté par spécifications. Kiro utilise les « Specs » (exigences en langage naturel qui pilotent l'implémentation complète) et les « Hooks » (déclencheurs automatiques à l'enregistrement d'un fichier ou lors d'un commit). Le support du plugin IDE prendra fin le 30 avril 2027.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'fr';

UPDATE news SET title = $t$Plugin do Amazon Q Developer para IDE é substituído pelo Kiro — novo IDE agentivo orientado a especificações$t$, summary = $t$A AWS bloqueou novos cadastros no plugin do Amazon Q Developer para IDE a partir de 15 de maio de 2026, anunciando seu substituto: o Kiro, um IDE agentivo orientado a especificações. O Kiro utiliza "Specs" (requisitos em linguagem natural que guiam a implementação completa) e "Hooks" (acionadores automáticos ao salvar arquivos ou fazer commit). O suporte ao plugin de IDE termina em 30 de abril de 2027.$t$
 WHERE slug = 'amazon-q-developer-replaced-by-kiro' AND lang = 'pt';

UPDATE news SET title = $t$Anthropic lanza Claude Design, una IA que crea imágenes visuales coherentes con la marca$t$, summary = $t$Anthropic presentó Claude Design, su primer producto dedicado al diseño, como parte de Anthropic Labs. Construido sobre Claude Opus 4.7, genera presentaciones de diapositivas, mockups y materiales de marketing a partir de una conversación, con generación automática de sistemas de marca a partir de bases de código o archivos de diseño existentes. Está disponible sin costo adicional para los suscriptores de Claude Pro, Max, Team y Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'es';

UPDATE news SET title = $t$Anthropic startet Claude Design — KI erstellt markenkonforme Visuals$t$, summary = $t$Anthropic hat Claude Design veröffentlicht, sein erstes eigenständiges Design-Produkt im Rahmen von Anthropic Labs. Das auf Claude Opus 4.7 basierende Tool erstellt aus Konversationen heraus Präsentationen, Mockups und Marketingmaterialien — inklusive automatischer Generierung von Markensystemen aus bestehenden Codebasen oder Design-Dateien. Verfügbar ohne Zusatzkosten für Claude Pro-, Max-, Team- und Enterprise-Abonnenten.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'de';

UPDATE news SET title = $t$Anthropic представила Claude Design — ИИ для создания визуалов в едином фирменном стиле$t$, summary = $t$Anthropic выпустила Claude Design — свой первый специализированный продукт для дизайна в рамках Anthropic Labs. Инструмент работает на базе Claude Opus 4.7 и создаёт презентации, макеты и маркетинговые материалы на основе диалога, включая автоматическое формирование фирменного стиля на основе существующих кодовых баз или файлов дизайна. Доступен без дополнительной оплаты для подписчиков Claude Pro, Max, Team и Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'ru';

UPDATE news SET title = $t$Anthropic випустила Claude Design — ШІ, що створює візуали в стилі бренду$t$, summary = $t$Anthropic представила Claude Design — свій перший спеціалізований продукт для дизайну в межах Anthropic Labs. Побудований на Claude Opus 4.7, він генерує презентації, макети та маркетингові матеріали на основі діалогу, а також автоматично формує брендбук на основі наявного коду чи дизайн-файлів. Доступний без додаткової плати для передплатників Claude Pro, Max, Team та Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'ua';

UPDATE news SET title = $t$Anthropic משיקה את Claude Design — כלי AI ליצירת עיצובים עקביים למותג$t$, summary = $t$Anthropic השיקה את Claude Design, מוצר העיצוב הראשון שלה, כחלק מ-Anthropic Labs. הכלי מבוסס על Claude Opus 4.7 ומייצר מצגות, מוקאפים וחומרי שיווק מתוך שיחה — עם יצירה אוטומטית של מערכת מותג מבסיסי קוד קיימים או קבצי עיצוב. הכלי זמין ללא תוספת עלות למנויי Claude Pro, Max, Team ו-Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'he';

UPDATE news SET title = $t$Anthropic lance Claude Design — une IA qui crée des visuels cohérents avec l'identité de marque$t$, summary = $t$Anthropic a lancé Claude Design, son premier produit dédié au design, dans le cadre d'Anthropic Labs. Basé sur Claude Opus 4.7, il génère des présentations, des maquettes et des supports marketing à partir d'une conversation — avec génération automatique d'une charte graphique à partir de bases de code ou de fichiers de design existants. Disponible sans coût supplémentaire pour les abonnés Claude Pro, Max, Team et Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'fr';

UPDATE news SET title = $t$Anthropic lança Claude Design — IA que cria visuais consistentes com a marca$t$, summary = $t$A Anthropic lançou o Claude Design, seu primeiro produto dedicado a design, como parte do Anthropic Labs. Construído sobre o Claude Opus 4.7, ele gera apresentações de slides, mockups e materiais de marketing a partir de conversas — com geração automática de sistema de marca a partir de bases de código ou arquivos de design existentes. Disponível sem custo adicional para assinantes do Claude Pro, Max, Team e Enterprise.$t$
 WHERE slug = 'anthropic-claude-design-launch' AND lang = 'pt';

UPDATE news SET title = $t$Cursor 3.4 lanza entornos de desarrollo agénticos con soporte para multirrepositorio y agentes en paralelo$t$, summary = $t$Cursor 3.4 introduce entornos de desarrollo agénticos: los agentes ahora aprovisionan entornos definidos mediante Dockerfile, trabajan simultáneamente en múltiples repositorios y se ejecutan en paralelo. Cursor 3.3 había añadido la revisión de PR dentro del editor. BugBot pasará a facturación basada en uso a partir de junio de 2026.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'es';

UPDATE news SET title = $t$Cursor 3.4 startet agentische Entwicklungsumgebungen mit Unterstützung für Multi-Repo und parallele Agenten$t$, summary = $t$Cursor 3.4 führt agentische Entwicklungsumgebungen ein: Agenten richten nun Dockerfile-definierte Umgebungen ein, arbeiten gleichzeitig über mehrere Repositories hinweg und laufen parallel. Cursor 3.3 hatte bereits PR-Reviews direkt im Editor eingeführt. BugBot wechselt ab Juni 2026 zu einer nutzungsbasierten Abrechnung.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'de';

UPDATE news SET title = $t$Cursor 3.4 представляет агентные среды разработки с поддержкой мультирепозиториев и параллельных агентов$t$, summary = $t$Cursor 3.4 вводит агентные среды разработки: агенты теперь развёртывают среды, описанные в Dockerfile, работают одновременно с несколькими репозиториями и выполняются параллельно. В Cursor 3.3 была добавлена проверка PR прямо в редакторе. BugBot переходит на биллинг по фактическому использованию с июня 2026 года.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'ru';

UPDATE news SET title = $t$Cursor 3.4 представляє агентні середовища розробки з підтримкою кількох репозиторіїв і паралельних агентів$t$, summary = $t$Cursor 3.4 запроваджує агентні середовища розробки: агенти тепер розгортають середовища, визначені у Dockerfile, працюють одночасно з кількома репозиторіями та виконуються паралельно. У Cursor 3.3 було додано перегляд PR прямо в редакторі. BugBot переходить на оплату за фактичне використання з червня 2026 року.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'ua';

UPDATE news SET title = $t$Cursor 3.4 משיקה סביבות פיתוח אג'נטיות עם תמיכה במספר מאגרים והרצת סוכנים במקביל$t$, summary = $t$Cursor 3.4 מציגה סביבות פיתוח אג'נטיות: הסוכנים מקצים כעת סביבות המוגדרות על ידי Dockerfile, פועלים על פני מספר מאגרי קוד (repositories) בו-זמנית, ורצים במקביל. Cursor 3.3 הוסיפה קודם לכן סקירת PR בתוך העורך. BugBot יעבור לחיוב מבוסס שימוש מיוני 2026.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'he';

UPDATE news SET title = $t$Cursor 3.4 lance des environnements de développement agentiques avec prise en charge multi-dépôts et agents en parallèle$t$, summary = $t$Cursor 3.4 introduit des environnements de développement agentiques : les agents provisionnent désormais des environnements définis par Dockerfile, travaillent simultanément sur plusieurs dépôts et s'exécutent en parallèle. Cursor 3.3 avait ajouté la revue de PR directement dans l'éditeur. BugBot passera à une facturation à l'usage à partir de juin 2026.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'fr';

UPDATE news SET title = $t$Cursor 3.4 lança ambientes de desenvolvimento agênticos com suporte a multi-repositórios e agentes paralelos$t$, summary = $t$O Cursor 3.4 introduz ambientes de desenvolvimento agênticos: os agentes agora provisionam ambientes definidos por Dockerfile, trabalham em múltiplos repositórios simultaneamente e executam tarefas em paralelo. O Cursor 3.3 havia adicionado revisão de PR dentro do editor. O BugBot passa para cobrança baseada em uso a partir de junho de 2026.$t$
 WHERE slug = 'cursor-34-agentic-dev-environments' AND lang = 'pt';

UPDATE news SET title = $t$OpenAI retira DALL-E 2 y DALL-E 3, sustituidos por gpt-image-2$t$, summary = $t$OpenAI retiró oficialmente DALL-E 2 y DALL-E 3 el 12 de mayo de 2026. Ambos son reemplazados por el modelo gpt-image-2, que impulsa ChatGPT Images 2.0 con resolución nativa de 2K, renderizado de texto multilingüe y hasta 8 imágenes por solicitud en modo de razonamiento.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'es';

UPDATE news SET title = $t$OpenAI stellt DALL-E 2 und DALL-E 3 ein — ersetzt durch gpt-image-2$t$, summary = $t$OpenAI hat DALL-E 2 und DALL-E 3 am 12. Mai 2026 offiziell eingestellt. Beide werden durch das Modell gpt-image-2 ersetzt, das ChatGPT Images 2.0 antreibt und native 2K-Auflösung, mehrsprachiges Text-Rendering sowie bis zu 8 Bilder pro Prompt im Denkmodus bietet.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'de';

UPDATE news SET title = $t$OpenAI прекращает поддержку DALL-E 2 и DALL-E 3 — их заменит gpt-image-2$t$, summary = $t$OpenAI официально прекратила поддержку DALL-E 2 и DALL-E 3 12 мая 2026 года. Обе модели заменены на gpt-image-2, которая лежит в основе ChatGPT Images 2.0 с нативным разрешением 2K, многоязычным рендерингом текста и генерацией до 8 изображений на запрос в режиме размышления.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'ru';

UPDATE news SET title = $t$OpenAI припиняє підтримку DALL-E 2 та DALL-E 3 — на заміну приходить gpt-image-2$t$, summary = $t$OpenAI офіційно припинила підтримку DALL-E 2 та DALL-E 3 12 травня 2026 року. Обидві моделі замінені моделлю gpt-image-2, яка лежить в основі ChatGPT Images 2.0 з нативною роздільною здатністю 2K, багатомовним рендерингом тексту та можливістю генерувати до 8 зображень на запит у режимі мислення.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'ua';

UPDATE news SET title = $t$OpenAI מוציאה את DALL-E 2 ו-DALL-E 3 משימוש — מוחלפים ב-gpt-image-2$t$, summary = $t$OpenAI הוציאה רשמית את DALL-E 2 ו-DALL-E 3 משימוש בתאריך 12 במאי 2026. שני המודלים מוחלפים במודל gpt-image-2, המפעיל את ChatGPT Images 2.0 עם רזולוציית 2K מובנית, עיבוד טקסט רב-לשוני, ועד 8 תמונות לכל בקשה במצב חשיבה (thinking mode).$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'he';

UPDATE news SET title = $t$OpenAI retire DALL-E 2 et DALL-E 3 — remplacés par gpt-image-2$t$, summary = $t$OpenAI a officiellement retiré DALL-E 2 et DALL-E 3 le 12 mai 2026. Les deux modèles sont remplacés par gpt-image-2, qui alimente ChatGPT Images 2.0 avec une résolution native de 2K, un rendu de texte multilingue et jusqu'à 8 images par requête en mode réflexion.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'fr';

UPDATE news SET title = $t$OpenAI Descontinua DALL-E 2 e DALL-E 3 — Substituídos pelo gpt-image-2$t$, summary = $t$A OpenAI descontinuou oficialmente o DALL-E 2 e o DALL-E 3 em 12 de maio de 2026. Ambos são substituídos pelo modelo gpt-image-2, que alimenta o ChatGPT Images 2.0 com resolução nativa em 2K, renderização de texto multilíngue e até 8 imagens por prompt no modo thinking.$t$
 WHERE slug = 'dalle-3-retired-gpt-image-2-replaces' AND lang = 'pt';

UPDATE news SET title = $t$El servidor MCP de Figma permite que agentes de IA diseñen directamente en el lienzo, además de herramientas de IA para imágenes y entrada por voz$t$, summary = $t$Figma lanzó un servidor MCP (Model Context Protocol) que permite que agentes de IA como Cursor y Claude creen y editen diseños directamente en el lienzo de Figma. Las herramientas de IA para imágenes integradas ahora incluyen Vectorize, Remove Background, Erase y Expand, eliminando la necesidad de exportar a Photoshop. También están disponibles la entrada por voz y el texto sobre trayectoria.$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'es';

UPDATE news SET title = $t$Figma MCP-Server ermöglicht KI-Agenten direktes Design auf der Canvas — plus integrierte KI-Bildwerkzeuge und Spracheingabe$t$, summary = $t$Figma hat einen MCP-Server (Model Context Protocol) eingeführt, mit dem KI-Agenten wie Cursor und Claude Designs direkt auf der Figma-Canvas erstellen und bearbeiten können. Die integrierten KI-Bildwerkzeuge umfassen jetzt Vectorize, Remove Background, Erase und Expand — der Export nach Photoshop entfällt damit. Außerdem sind nun Spracheingabe und Text auf Pfad verfügbar.$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'de';

UPDATE news SET title = $t$MCP-сервер Figma позволяет AI-агентам проектировать прямо на холсте — плюс встроенные AI-инструменты для изображений и голосовой ввод$t$, summary = $t$Figma запустила MCP-сервер (Model Context Protocol), который позволяет AI-агентам, таким как Cursor и Claude, создавать и редактировать дизайны прямо на холсте Figma. Встроенные AI-инструменты для изображений теперь включают Vectorize, Remove Background, Erase и Expand — это избавляет от необходимости экспортировать файлы в Photoshop. Также стали доступны голосовой ввод и текст по контуру.$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'ru';

UPDATE news SET title = $t$MCP-сервер Figma дозволяє AI-агентам створювати дизайн прямо на канвасі — плюс вбудовані інструменти AI для зображень і голосове введення$t$, summary = $t$Figma запустила MCP-сервер (Model Context Protocol), що дозволяє AI-агентам, таким як Cursor і Claude, створювати та редагувати дизайни прямо на канвасі Figma. Вбудовані інструменти AI Image Tools тепер включають Vectorize, Remove Background, Erase та Expand — це усуває потребу експортувати роботу в Photoshop. Також стали доступні голосове введення та текст уздовж контуру (text on path).$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'ua';

UPDATE news SET title = $t$שרת MCP של Figma מאפשר לסוכני AI לעצב ישירות על משטח העבודה — וגם כלי תמונה מבוססי AI ותמיכה בקול$t$, summary = $t$Figma השיקה שרת MCP (Model Context Protocol) המאפשר לסוכני AI כמו Cursor ו-Claude ליצור ולערוך עיצובים ישירות על משטח העבודה של Figma. כלי AI Image Tools המובנים כוללים כעת Vectorize, Remove Background, Erase ו-Expand — כך שאין צורך יותר לייצא לפוטושופ. כמו כן נוספו קלט קולי (Voice input) ואפשרות טקסט על נתיב (text on path).$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'he';

UPDATE news SET title = $t$Le serveur MCP de Figma permet aux agents IA de concevoir directement sur le canevas — avec en prime des outils d'image IA intégrés et une saisie vocale$t$, summary = $t$Figma a lancé un serveur MCP (Model Context Protocol) permettant à des agents IA comme Cursor et Claude de créer et modifier des designs directement sur le canevas de Figma. Les outils d'image IA intégrés comprennent désormais Vectorize, Remove Background, Erase et Expand, supprimant le besoin d'exporter vers Photoshop. La saisie vocale et le texte sur tracé sont également désormais disponibles.$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'fr';

UPDATE news SET title = $t$Servidor MCP do Figma Permite que Agentes de IA Projetem Diretamente no Canvas — Além de Ferramentas de Imagem com IA e Entrada por Voz$t$, summary = $t$O Figma lançou um servidor MCP (Model Context Protocol) que permite que agentes de IA, como Cursor e Claude, criem e editem designs diretamente no canvas do Figma. As ferramentas de imagem com IA integradas agora incluem Vectorize, Remove Background, Erase e Expand — eliminando a necessidade de exportar para o Photoshop. Entrada por voz e texto em trajetória também já estão disponíveis.$t$
 WHERE slug = 'figma-mcp-server-ai-agents-canvas' AND lang = 'pt';

UPDATE news SET title = $t$Google anuncia Gemini Intelligence para Android: automatiza tareas de varios pasos en Samsung y Pixel$t$, summary = $t$En el Google Android Show 2026, Google presentó Gemini Intelligence, una nueva capa que automatiza tareas de varios pasos, como compras, reservas y gestión de calendario, directamente en dispositivos Android. Llegará a teléfonos Samsung y Google en el verano de 2026. Google también anunció Googlebooks, nuevas laptops con Android de Acer, ASUS y Lenovo con Gemini integrado.$t$
 WHERE slug = 'google-gemini-intelligence-android-2026' AND lang = 'es';

