UPDATE news SET title = $t$HeyGen скасовує безлімітні тарифні плани — усі нові плани з 15 травня 2026 року на основі кредитів$t$, summary = $t$HeyGen припинила підтримку застарілих безлімітних тарифних планів для відеоаватарів 15 травня 2026 року. Усі нові підписки HeyGen тепер працюють на основі кредитів. Разом із перебудовою тарифів були представлені Avatar V, здатний створювати контент студійної якості з 15 секунд відеозапису, та інтеграція з Seedance 2.0.$t$
 WHERE slug = 'heygen-pricing-legacy-unlimited-removed' AND lang = 'ua';

UPDATE news SET title = $t$HeyGen מבטלת את התוכניות הישנות ללא הגבלה — כל התוכניות החדשות מבוססות קרדיטים מ-15 במאי 2026$t$, summary = $t$HeyGen הפסיקה את תוכניות הווידאו הישנות עם אווטארים ללא הגבלה ב-15 במאי 2026. כל המנויים החדשים של HeyGen מבוססים כעת על קרדיטים. Avatar V, המאפשר פלט באיכות אולפן מ-15 שניות של צילום, ואינטגרציית הווידאו Seedance 2.0 הושקו במקביל לשינוי מבנה התמחור.$t$
