UPDATE news SET title = $t$HeyGen elimina planos ilimitados legados — todos os novos planos passam a ser baseados em créditos a partir de 15 de maio de 2026$t$, summary = $t$A HeyGen descontinuou os planos legados de vídeo com avatar ilimitado em 15 de maio de 2026. Todas as novas assinaturas da HeyGen agora são baseadas em créditos. O Avatar V, capaz de gerar resultados com qualidade de estúdio a partir de 15 segundos de filmagem, e a integração com o Seedance 2.0 foram lançados junto com a reestruturação de preços.$t$
