UPDATE news SET title = $t$Kling v3.5 — 1080p/60fps, clips Pro de hasta 2 minutos, física mejorada, escisión de Kuaishou valorada en ~20 mil millones de dólares$t$, summary = $t$Kling AI lanzó la v3.5 con salida nativa en 1080p/60fps, duración de clip Pro ampliada hasta 2 minutos (la generación individual más larga disponible) y física de movimiento mejorada para dinámica de fluidos y simulación de telas. Kuaishou está evaluando escindir Kling AI como empresa independiente con una valoración aproximada de 20 mil millones de dólares.$t$
