UPDATE news SET title = $t$Kling v3.5 — 1080p/60fps, Pro-Clips bis zu 2 Minuten, verbesserte Physik, Kuaishou-Ausgliederung mit Bewertung von ~20 Mrd. USD geprüft$t$, summary = $t$Kling AI hat v3.5 veröffentlicht, mit nativer 1080p/60fps-Ausgabe, verlängerter Clip-Länge im Pro-Tarif auf bis zu 2 Minuten (die längste verfügbare Einzelgenerierung) sowie verbesserter Bewegungsphysik für Fluiddynamik und Stoffsimulation. Kuaishou prüft eine Ausgliederung von Kling AI als eigenständiges Unternehmen bei einer Bewertung von rund 20 Milliarden US-Dollar.$t$
 WHERE slug = 'kling-v35-1080p-60fps-2min' AND lang = 'de';

UPDATE news SET title = $t$Kling v3.5: 1080p/60fps, клипы Pro до 2 минут, улучшенная физика, выделение из Kuaishou с оценкой около $20 млрд$t$, summary = $t$Kling AI выпустила версию v3.5 с нативным выводом в 1080p/60fps, увеличенной длиной клипов уровня Pro до 2 минут (самая длинная доступная одиночная генерация) и улучшенной физикой движения для гидродинамики и симуляции ткани. Kuaishou рассматривает возможность выделения Kling AI в независимую компанию с оценкой примерно в $20 миллиардов.$t$
 WHERE slug = 'kling-v35-1080p-60fps-2min' AND lang = 'ru';

UPDATE news SET title = $t$Kling v3.5 — 1080p/60fps, Pro-клипи до 2 хвилин, покращена фізика, спін-офф Kuaishou оцінюють у ~20 млрд доларів$t$, summary = $t$Kling AI випустила версію v3.5 із рідною підтримкою 1080p/60fps, збільшеною тривалістю Pro-клипів до 2 хвилин (найдовша одноразова генерація на ринку) та покращеною фізикою руху для симуляції рідин і тканини. Kuaishou розглядає можливість виокремлення Kling AI в незалежну компанію з оцінкою приблизно 20 мільярдів доларів.$t$
 WHERE slug = 'kling-v35-1080p-60fps-2min' AND lang = 'ua';

UPDATE news SET title = $t$Kling v3.5 — פלט 1080p/60fps, קליפים ב-Pro באורך של עד 2 דקות, שיפור בפיזיקה, ופיצול Kuaishou המוערך בכ-20 מיליארד דולר$t$, summary = $t$Kling AI השיקה את v3.5 עם פלט 1080p/60fps מובנה, הארכת אורך הקליפים במסלול Pro עד 2 דקות (היצירה הבודדת הארוכה ביותר הזמינה כיום), ושיפור בפיזיקת התנועה עבור דינמיקת נוזלים וסימולציית בדים. Kuaishou בוחנת פיצול של Kling AI לחברה עצמאית בשווי של כ-20 מיליארד דולר.$t$
 WHERE slug = 'kling-v35-1080p-60fps-2min' AND lang = 'he';

UPDATE news SET title = $t$Kling v3.5 — 1080p/60ips, clips Pro jusqu'à 2 minutes, physique améliorée, la scission de Kuaishou évaluée à ~20 milliards de dollars$t$, summary = $t$Kling AI a lancé la v3.5 avec une sortie native en 1080p/60ips, une durée de clip en niveau Pro étendue jusqu'à 2 minutes (la génération unique la plus longue disponible), et une physique de mouvement améliorée pour la dynamique des fluides et la simulation de tissus. Kuaishou étudie la possibilité de scinder Kling AI en une société indépendante, avec une valorisation d'environ 20 milliards de dollars.$t$
 WHERE slug = 'kling-v35-1080p-60fps-2min' AND lang = 'fr';

UPDATE news SET title = $t$Kling v3.5 — 1080p/60fps, Clipes Pro de Até 2 Minutos, Física Aprimorada, Spin-Off da Kuaishou Avaliado em ~US$ 20 Bilhões$t$, summary = $t$A Kling AI lançou a v3.5 com saída nativa em 1080p/60fps, duração estendida dos clipes do plano Pro para até 2 minutos (a geração única mais longa disponível) e física de movimento aprimorada para dinâmica de fluidos e simulação de tecidos. A Kuaishou está avaliando separar a Kling AI como uma empresa independente, com uma avaliação de aproximadamente US$ 20 bilhões.$t$
