UPDATE news SET title = $t$Krea lanza Krea 2: nuevo modelo de imagen fundacional creado desde cero$t$, summary = $t$Krea AI presentó su modelo fundacional Krea 2, desarrollado desde cero con énfasis en la estética y la transferencia de estilo. El lanzamiento se acompaña de Krea Nodes (creación de flujos de trabajo de imágenes a partir de descripciones de texto) y Krea Edit (edición por regiones, reiluminación, expansión de imágenes). Seedance 2.0 ya está disponible en todos los planes de pago.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'es';

UPDATE news SET title = $t$Krea bringt Krea 2 auf den Markt — neues Foundation-Bildmodell komplett neu entwickelt$t$, summary = $t$Krea AI hat sein Foundation-Modell Krea 2 veröffentlicht, das von Grund auf neu entwickelt wurde und den Schwerpunkt auf Ästhetik und Stilübertragung legt. Zum Start gehören außerdem Krea Nodes (Bild-Workflows aus Textbeschreibungen erstellen) und Krea Edit (Bereichsbearbeitung, Relighting, Bilderweiterung). Seedance 2.0 ist nun in allen kostenpflichtigen Plänen verfügbar.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'de';

UPDATE news SET title = $t$Krea выпустила Krea 2 — новую базовую модель для генерации изображений, созданную с нуля$t$, summary = $t$Krea AI представила базовую модель Krea 2, разработанную с нуля с акцентом на эстетику и перенос стиля. Запуск сопровождается выходом Krea Nodes (создание рабочих процессов для изображений по текстовым описаниям) и Krea Edit (редактирование областей, изменение освещения, расширение изображения). Seedance 2.0 теперь доступна на всех платных тарифах.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'ru';

UPDATE news SET title = $t$Krea випустила Krea 2 — нову базову модель для генерації зображень, створену з нуля$t$, summary = $t$Krea AI випустила базову модель Krea 2, розроблену з нуля з акцентом на естетику та перенесення стилю. Запуск супроводжується Krea Nodes (створення робочих процесів для зображень з текстових описів) та Krea Edit (редагування ділянок, релайтинг, розширення зображення). Seedance 2.0 тепер доступна на всіх платних тарифах.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'ua';

UPDATE news SET title = $t$Krea משיקה את Krea 2 — מודל תמונות בסיסי חדש שנבנה מאפס$t$, summary = $t$חברת Krea AI פרסמה את מודל הבסיס Krea 2, שנבנה מאפס בדגש על אסתטיקה והעברת סטייל. ההשקה מגיעה בליווי Krea Nodes (בניית תהליכי עבודה ליצירת תמונות מתיאורים טקסטואליים) ו-Krea Edit (עריכת אזורים בתמונה, שינוי תאורה והרחבת תמונה). כמו כן, Seedance 2.0 זמין כעת בכל התוכניות בתשלום.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'he';

UPDATE news SET title = $t$Krea lance Krea 2 — nouveau modèle d'image fondamental conçu à partir de zéro$t$, summary = $t$Krea AI a lancé son modèle fondamental Krea 2, conçu entièrement à partir de zéro avec un accent sur l'esthétique et le transfert de style. Ce lancement s'accompagne de Krea Nodes (créer des workflows d'image à partir de descriptions textuelles) et de Krea Edit (édition par région, reéclairage, expansion d'image). Seedance 2.0 est désormais disponible sur tous les forfaits payants.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'fr';

UPDATE news SET title = $t$Krea Lança Krea 2 — Novo Modelo Fundacional de Imagem Construído do Zero$t$, summary = $t$A Krea AI lançou seu modelo fundacional Krea 2, construído do zero com foco em estética e transferência de estilo. O lançamento vem acompanhado do Krea Nodes (cria fluxos de trabalho de imagem a partir de descrições em texto) e do Krea Edit (edição por região, reiluminação, expansão de imagem). O Seedance 2.0 já está disponível em todos os planos pagos.$t$
 WHERE slug = 'krea-ai-krea-2-foundation-model' AND lang = 'pt';

UPDATE news SET title = $t$Luma Ray3.14: 1080p nativo, 4 veces más rápido, 3 veces más barato, Character Seeds y edición mediante instrucciones$t$, summary = $t$Luma AI lanzó Ray3.14 con salida de video en 1080p nativo (sin escalado), una velocidad de generación 4 veces más rápida que Ray2 y un costo 3 veces menor por segundo generado. Character Seeds mantiene una apariencia de personaje consistente en múltiples clips. Modify with Instructions permite realizar ediciones guiadas por texto después de la generación sin necesidad de regenerar todo el contenido.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'es';

UPDATE news SET title = $t$Luma Ray3.14 — Natives 1080p, 4x schneller, 3x geringere Kosten, Character Seeds, Bearbeitung per Anweisung$t$, summary = $t$Luma AI hat Ray3.14 veröffentlicht, mit nativer 1080p-Videoausgabe (ohne Upscaling), einer Generierungsgeschwindigkeit, die 4x schneller ist als bei Ray2, und 3x geringeren Kosten pro generierter Sekunde. Character Seeds sorgen für ein konsistentes Erscheinungsbild von Charakteren über mehrere Clips hinweg. Modify with Instructions ermöglicht textgesteuerte Bearbeitungen nach der Generierung, ohne dass eine vollständige Neugenerierung nötig ist.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'de';

UPDATE news SET title = $t$Luma Ray3.14 — нативное 1080p, в 4 раза быстрее, в 3 раза дешевле, Character Seeds, редактирование по инструкциям$t$, summary = $t$Luma AI выпустила Ray3.14 с нативной генерацией видео в 1080p (без апскейлинга), скоростью генерации в 4 раза выше, чем у Ray2, и стоимостью за сгенерированную секунду в 3 раза ниже. Функция Character Seeds обеспечивает сохранение внешности персонажа в нескольких клипах. Modify with Instructions позволяет вносить правки после генерации по текстовым инструкциям без полной перегенерации.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'ru';

UPDATE news SET title = $t$Luma Ray3.14 — рідне 1080p, у 4 рази швидше, у 3 рази дешевше, Character Seeds, редагування за інструкціями$t$, summary = $t$Luma AI випустила Ray3.14 із рідною підтримкою відео у 1080p (без апскейлінгу), швидкістю генерації у 4 рази вищою за Ray2 та вартістю за секунду генерації, нижчою у 3 рази. Функція Character Seeds забезпечує стабільний вигляд персонажа в кількох клипах. Modify with Instructions дозволяє редагувати вже згенероване відео за текстовими інструкціями без повної повторної генерації.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'ua';

UPDATE news SET title = $t$Luma Ray3.14 — פלט 1080p טבעי, מהיר פי 4, בעלות נמוכה פי 3, Character Seeds ועריכה באמצעות הוראות טקסט$t$, summary = $t$Luma AI השיקה את Ray3.14 עם פלט וידאו ברזולוציית 1080p טבעית (ללא הגדלת רזולוציה), מהירות יצירה מהירה פי 4 בהשוואה ל-Ray2, ועלות לשנייה מיוצרת נמוכה פי 3. תכונת Character Seeds שומרת על מראה עקבי של דמויות בין כמה קליפים. תכונת Modify with Instructions מאפשרת ערכי עריכה מבוססי טקסט לאחר היצירה, בלי צורך ביצירה מלאה מחדש.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'he';

UPDATE news SET title = $t$Luma Ray3.14 — 1080p natif, 4x plus rapide, coût 3x inférieur, Character Seeds, modification par instructions$t$, summary = $t$Luma AI a lancé Ray3.14 avec une sortie vidéo en 1080p natif (sans upscaling), une vitesse de génération 4x plus rapide que Ray2, et un coût par seconde générée 3x inférieur. Les Character Seeds permettent de conserver une apparence de personnage cohérente sur plusieurs clips. La fonction Modify with Instructions permet des modifications post-génération guidées par texte, sans régénération complète.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'fr';

UPDATE news SET title = $t$Luma Ray3.14 — 1080p Nativo, 4x Mais Rápido, Custo 3x Menor, Character Seeds, Modificação com Instruções$t$, summary = $t$A Luma AI lançou o Ray3.14 com saída de vídeo em 1080p nativo (sem upscaling), velocidade de geração 4x mais rápida que o Ray2 e custo por segundo gerado 3x menor. O recurso Character Seeds mantém a aparência consistente de personagens em múltiplos clipes. Já o Modify with Instructions permite edições pós-geração guiadas por texto, sem necessidade de regeneração completa.$t$
 WHERE slug = 'luma-ray314-1080p-4x-faster' AND lang = 'pt';

UPDATE news SET title = $t$Midjourney V8.1: renderizado nativo en 2K, hasta 3-4 veces más rápido, modo Raw y perfiles públicos de creadores$t$, summary = $t$Midjourney V8.1 ofrece salida en resolución nativa 2K, una velocidad de generación de 3 a 4 veces más rápida que V7, y el modo Raw para una interpretación más literal de los prompts. Los perfiles públicos permiten a los creadores compartir su trabajo socialmente. Midjourney TV se lanza como una transmisión en tiempo real de las creaciones de la comunidad. Se ha anunciado V8.2 como la próxima versión.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'es';

UPDATE news SET title = $t$Midjourney V8.1 — Natives 2K-Rendering, 3–4x schneller, Raw-Modus und öffentliche Creator-Profile$t$, summary = $t$Midjourney V8.1 bietet native 2K-Auflösung, eine Generierungsgeschwindigkeit, die 3 bis 4 Mal schneller ist als bei V7, sowie einen Raw-Modus für eine wörtlichere Interpretation von Prompts. Öffentliche Profile ermöglichen es Creators, ihre Arbeiten sozial zu teilen. Midjourney TV startet als Echtzeit-Stream von Community-Generierungen. V8.2 wurde als nächstes Release angekündigt.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'de';

UPDATE news SET title = $t$Midjourney V8.1: нативный рендеринг 2K, ускорение в 3-4 раза, режим Raw и публичные профили авторов$t$, summary = $t$Midjourney V8.1 обеспечивает вывод изображений в нативном разрешении 2K, скорость генерации в 3-4 раза выше, чем у V7, и режим Raw для более буквальной интерпретации промптов. Публичные профили позволяют авторам делиться своими работами в соцсетях. Запущен Midjourney TV — трансляция генераций сообщества в реальном времени. Анонсирован следующий релиз — V8.2.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'ru';

UPDATE news SET title = $t$Midjourney V8.1 — рідний рендеринг у 2K, швидкість у 3-4 рази вища, режим Raw і публічні профілі авторів$t$, summary = $t$Midjourney V8.1 забезпечує нативний вивід у роздільній здатності 2K, швидкість генерації в 3-4 рази вищу порівняно з V7, а також режим Raw для більш буквальної інтерпретації запитів. Публічні профілі дозволяють авторам ділитися своїми роботами в соціальному форматі. Запущено Midjourney TV — потокову трансляцію генерацій спільноти в реальному часі. Наступним релізом анонсовано V8.2.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'ua';

UPDATE news SET title = $t$Midjourney V8.1 — רינדור 2K ילידי, מהירות פי 3-4, מצב Raw ופרופילי יוצרים ציבוריים$t$, summary = $t$Midjourney V8.1 מציגה פלט ברזולוציית 2K ילידית, מהירות יצירה מהירה פי 3 עד 4 בהשוואה ל-V7, ומצב Raw לפרשנות מילולית יותר של הפרומפט. פרופילים ציבוריים מאפשרים ליוצרים לשתף את עבודתם באופן חברתי. Midjourney TV משיקה כשידור בזמן אמת של יצירות הקהילה. V8.2 הוכרזה כגרסה הבאה.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'he';

UPDATE news SET title = $t$Midjourney V8.1 : rendu natif en 2K, vitesse 3 à 4 fois supérieure, mode Raw et profils publics pour les créateurs$t$, summary = $t$Midjourney V8.1 propose une sortie en résolution native 2K, une vitesse de génération 3 à 4 fois plus rapide que V7, ainsi qu'un mode Raw pour une interprétation plus littérale des prompts. Les profils publics permettent aux créateurs de partager leurs œuvres sur les réseaux sociaux. Midjourney TV fait ses débuts sous forme de flux en temps réel des créations de la communauté. La version V8.2 a été annoncée comme prochaine mise à jour.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'fr';

UPDATE news SET title = $t$Midjourney V8.1 — Renderização Nativa em 2K, 3 a 4 Vezes Mais Rápido, Modo Raw e Perfis Públicos de Criadores$t$, summary = $t$O Midjourney V8.1 traz saída nativa em resolução 2K, velocidade de geração de 3 a 4 vezes mais rápida que o V7, e o modo Raw para uma interpretação mais literal dos prompts. Perfis públicos permitem que criadores compartilhem seus trabalhos socialmente. O Midjourney TV é lançado como uma transmissão em tempo real das criações da comunidade. O V8.2 já foi anunciado como o próximo lançamento.$t$
 WHERE slug = 'midjourney-v81-2k-public-profiles' AND lang = 'pt';

UPDATE news SET title = $t$Notion Developer Platform 3.5: entorno Workers, sincronización de bases de datos, webhooks bidireccionales y modo de planificación para agentes$t$, summary = $t$Notion lanzó Developer Platform 3.5 el 13 de mayo de 2026. El entorno Workers permite a los desarrolladores implementar lógica serverless en JavaScript dentro de Notion. Database Sync habilita conexiones bidireccionales con bases de datos externas. Bidirectional Webhooks permite que Notion reciba y envíe eventos. Plan Mode habilita agentes de IA autónomos de múltiples pasos dentro de los flujos de trabajo de Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'es';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — Workers Runtime, Datenbank-Synchronisierung, bidirektionale Webhooks und Agent-Planmodus$t$, summary = $t$Notion hat am 13. Mai 2026 die Developer Platform 3.5 veröffentlicht. Die Workers Runtime ermöglicht Entwicklern das Bereitstellen serverloser JavaScript-Logik innerhalb von Notion. Database Sync ermöglicht bidirektionale Verbindungen zu externen Datenbanken. Bidirektionale Webhooks erlauben es Notion, Events zu empfangen und zu senden. Der Plan Mode ermöglicht autonome, mehrstufige KI-Agenten innerhalb von Notion-Workflows.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'de';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — среда выполнения Workers, синхронизация баз данных, двунаправленные вебхуки и режим планирования агентов$t$, summary = $t$Notion выпустила Developer Platform 3.5 13 мая 2026 года. Среда выполнения Workers позволяет разработчикам развертывать серверless-логику на JavaScript внутри Notion. Database Sync обеспечивает двустороннее подключение к внешним базам данных. Bidirectional Webhooks позволяют Notion получать и отправлять события. Plan Mode включает автономных многошаговых AI-агентов в рабочих процессах Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'ru';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — середовище виконання Workers, синхронізація баз даних, двобічні вебхуки та режим планування агентів$t$, summary = $t$Notion випустила Developer Platform 3.5 13 травня 2026 року. Середовище виконання Workers дозволяє розробникам розгортати безсерверну логіку на JavaScript усередині Notion. Database Sync забезпечує двобічні з'єднання із зовнішніми базами даних. Bidirectional Webhooks дозволяють Notion отримувати та надсилати події. Plan Mode уможливлює автономних багатоетапних AI-агентів у робочих процесах Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'ua';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — Workers Runtime, סנכרון מסדי נתונים, Webhooks דו-כיווניים ומצב תכנון לסוכנים$t$, summary = $t$Notion השיקה את Developer Platform 3.5 ב-13 במאי 2026. סביבת ה-Workers Runtime מאפשרת למפתחים לפרוס לוגיקת JavaScript ללא שרת (serverless) בתוך Notion. Database Sync מאפשרת חיבורים דו-כיווניים למסדי נתונים חיצוניים. Bidirectional Webhooks מאפשרים ל-Notion לקבל ולשלוח אירועים. Plan Mode מאפשר סוכני AI אוטונומיים מרובי שלבים בתוך תהליכי העבודה של Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'he';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — Runtime Workers, synchronisation de bases de données, webhooks bidirectionnels et mode Plan pour agents$t$, summary = $t$Notion a lancé Developer Platform 3.5 le 13 mai 2026. Le runtime Workers permet aux développeurs de déployer une logique JavaScript sans serveur au sein de Notion. Database Sync permet des connexions bidirectionnelles avec des bases de données externes. Les webhooks bidirectionnels permettent à Notion de recevoir et d'envoyer des événements. Le mode Plan permet à des agents IA autonomes d'exécuter des tâches multi-étapes au sein des workflows Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'fr';

UPDATE news SET title = $t$Notion Developer Platform 3.5 — Workers Runtime, Sincronização de Banco de Dados, Webhooks Bidirecionais e Modo de Planejamento para Agentes$t$, summary = $t$A Notion lançou o Developer Platform 3.5 em 13 de maio de 2026. O Workers runtime permite que desenvolvedores implantem lógica serverless em JavaScript dentro do Notion. O Database Sync possibilita conexões bidirecionais com bancos de dados externos. Os Webhooks Bidirecionais permitem que o Notion receba e envie eventos. O Plan Mode viabiliza agentes de IA autônomos com múltiplas etapas dentro dos fluxos de trabalho do Notion.$t$
 WHERE slug = 'notion-developer-platform-35' AND lang = 'pt';

UPDATE news SET title = $t$OpenAI convierte a GPT-5.5 Instant en el modelo predeterminado de ChatGPT: 52.5% menos alucinaciones$t$, summary = $t$OpenAI reemplazó a GPT-5.3 Instant por GPT-5.5 Instant como modelo predeterminado en ChatGPT. El nuevo modelo presenta un 52.5% menos de alucinaciones en consultas de alto riesgo e integra memoria de conversaciones pasadas, Gmail y archivos guardados para los usuarios Plus y Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'es';

UPDATE news SET title = $t$OpenAI macht GPT-5.5 Instant zum Standardmodell in ChatGPT — 52,5 % weniger Halluzinationen$t$, summary = $t$OpenAI hat GPT-5.3 Instant als Standardmodell in ChatGPT durch GPT-5.5 Instant ersetzt. Das neue Modell liefert bei kritischen Anfragen 52,5 % weniger Halluzinationen und bindet für Plus- und Pro-Nutzer den Speicher aus vergangenen Unterhaltungen, Gmail und gespeicherten Dateien ein.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'de';

UPDATE news SET title = $t$OpenAI сделала GPT-5.5 Instant моделью по умолчанию в ChatGPT — на 52,5% меньше галлюцинаций$t$, summary = $t$OpenAI заменила GPT-5.3 Instant на GPT-5.5 Instant в качестве модели по умолчанию в ChatGPT. Новая модель показывает на 52,5% меньше галлюцинаций в ответах на важные запросы и учитывает память из прошлых разговоров, Gmail и сохранённых файлов для пользователей Plus и Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'ru';

UPDATE news SET title = $t$OpenAI зробила GPT-5.5 Instant стандартною моделлю ChatGPT — на 52.5% менше галюцинацій$t$, summary = $t$OpenAI замінила GPT-5.3 Instant на GPT-5.5 Instant як стандартну модель у ChatGPT. Нова модель демонструє на 52.5% менше галюцинацій у запитах з високими ризиками та інтегрує пам'ять про минулі розмови, Gmail і збережені файли для користувачів Plus та Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'ua';

UPDATE news SET title = $t$OpenAI הופכת את GPT-5.5 Instant לדגם הבררת המחדל של ChatGPT — 52.5% פחות הזיות$t$, summary = $t$OpenAI החליפה את GPT-5.3 Instant ב-GPT-5.5 Instant כדגם בררת המחדל ב-ChatGPT. הדגם החדש מציג 52.5% פחות הזיות בשאלות בעלות סיכון גבוה, ומשלב זיכרון משיחות קודמות, מ-Gmail ומקבצים שמורים למשתמשי Plus ו-Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'he';

UPDATE news SET title = $t$OpenAI fait de GPT-5.5 Instant le modèle par défaut de ChatGPT — 52,5 % d'hallucinations en moins$t$, summary = $t$OpenAI a remplacé GPT-5.3 Instant par GPT-5.5 Instant comme modèle par défaut dans ChatGPT. Le nouveau modèle réduit les hallucinations de 52,5 % sur les requêtes à fort enjeu et intègre la mémoire des conversations passées, de Gmail et des fichiers enregistrés pour les utilisateurs Plus et Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'fr';

UPDATE news SET title = $t$OpenAI torna GPT-5.5 Instant o modelo padrão do ChatGPT — 52,5% menos alucinações$t$, summary = $t$A OpenAI substituiu o GPT-5.3 Instant pelo GPT-5.5 Instant como modelo padrão no ChatGPT. O novo modelo apresenta 52,5% menos alucinações em prompts de alto risco e integra memória de conversas passadas, Gmail e arquivos salvos para usuários Plus e Pro.$t$
 WHERE slug = 'openai-gpt-55-instant-default-model' AND lang = 'pt';

UPDATE news SET title = $t$Pika 2.5 y PikaStream 1.0: video sin parpadeos, personajes estables y chat de video con IA en tiempo real$t$, summary = $t$Pika 2.5 elimina los artefactos de parpadeo y logra una apariencia estable de los personajes a lo largo de las escenas. PikaStream 1.0 lanza el chat de video con IA en tiempo real: los usuarios mantienen conversaciones en vivo con agentes de IA representados como personajes de video generados. Pika se está expandiendo hacia una plataforma de aplicación de video social con IA que combina creación, compartición e interacción con IA en tiempo real.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'es';

UPDATE news SET title = $t$Pika 2.5 und PikaStream 1.0 — flimmerfreies Video, stabile Charaktere, KI-Videochat in Echtzeit$t$, summary = $t$Pika 2.5 beseitigt Flimmerartefakte und sorgt für ein durchgängig stabiles Erscheinungsbild von Charakteren über verschiedene Szenen hinweg. PikaStream 1.0 führt KI-Videochat in Echtzeit ein: Nutzer führen Live-Gespräche mit KI-Agenten, die als generierte Video-Charaktere dargestellt werden. Pika baut sich zu einer KI-Social-Video-App-Plattform aus, die Erstellung, Teilen und KI-Interaktion in Echtzeit kombiniert.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'de';

UPDATE news SET title = $t$Pika 2.5 и PikaStream 1.0: видео без мерцания, стабильные персонажи и видеочат с ИИ в реальном времени$t$, summary = $t$Pika 2.5 устраняет артефакты мерцания и обеспечивает стабильный внешний вид персонажей в разных сценах. PikaStream 1.0 запускает видеочат с ИИ в реальном времени: пользователи ведут живые беседы с ИИ-агентами, отображаемыми как сгенерированные видеоперсонажи. Pika расширяется до платформы для ИИ-приложений социального видео, объединяющей создание контента, обмен им и взаимодействие с ИИ в реальном времени.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'ru';

UPDATE news SET title = $t$Pika 2.5 і PikaStream 1.0 — відео без мерехтіння, стабільні персонажі та відеочат з ШІ у реальному часі$t$, summary = $t$Pika 2.5 усуває артефакти мерехтіння та забезпечує стабільний вигляд персонажів у різних сценах. PikaStream 1.0 запускає відеочат з ШІ у реальному часі: користувачі спілкуються наживо з ШІ-агентами, відтвореними у вигляді згенерованих відеоперсонажів. Pika перетворюється на платформу для соціального відео на основі ШІ, що поєднує створення контенту, обмін ним та взаємодію з ШІ у реальному часі.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'ua';

UPDATE news SET title = $t$Pika 2.5 ו-PikaStream 1.0 — וידאו ללא הבהובים, דמויות עקביות וצ'אט וידאו בזמן אמת עם AI$t$, summary = $t$Pika 2.5 מבטלת פגמי הבהוב ומשמרת מראה עקבי של דמויות בין סצנות. PikaStream 1.0 משיקה צ'אט וידאו בזמן אמת מבוסס AI: משתמשים מקיימים שיחות חיות עם סוכני AI המוצגים כדמויות וידאו מיוצרות. Pika מתרחבת לפלטפורמת אפליקציית וידאו חברתית מבוססת AI המשלבת יצירה, שיתוף ואינטראקציה בזמן אמת עם AI.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'he';

UPDATE news SET title = $t$Pika 2.5 et PikaStream 1.0 — vidéo sans scintillement, personnages stables, chat vidéo IA en temps réel$t$, summary = $t$Pika 2.5 élimine les artefacts de scintillement et assure une apparence stable des personnages d'une scène à l'autre. PikaStream 1.0 lance un chat vidéo IA en temps réel : les utilisateurs échangent en direct avec des agents IA incarnés par des personnages vidéo générés. Pika étend son offre vers une plateforme d'application vidéo sociale basée sur l'IA, combinant création, partage et interaction IA en temps réel.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'fr';

UPDATE news SET title = $t$Pika 2.5 e PikaStream 1.0 — Vídeo Sem Cintilação, Personagens Estáveis e Chat em Vídeo com IA em Tempo Real$t$, summary = $t$O Pika 2.5 elimina artefatos de cintilação e mantém a aparência estável dos personagens entre cenas. O PikaStream 1.0 lança o chat em vídeo com IA em tempo real: os usuários têm conversas ao vivo com agentes de IA renderizados como personagens de vídeo gerados. A Pika está se expandindo para uma plataforma de aplicativo de vídeo social com IA, combinando criação, compartilhamento e interação com IA em tempo real.$t$
 WHERE slug = 'pika-25-pikastream-ai-social-app' AND lang = 'pt';

UPDATE news SET title = $t$Suno recauda una Serie D con una valoración de 5.000 millones de dólares, frente a los 2.450 millones de noviembre$t$, summary = $t$La plataforma de música con IA Suno está levantando una ronda Serie D con una valoración de 5.000 millones de dólares, más del doble de su valoración de noviembre de 2025, que era de 2.450 millones de dólares. La empresa cuenta ahora con 2 millones de suscriptores de pago y genera 7 millones de pistas al día.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'es';

UPDATE news SET title = $t$Suno sammelt Series-D-Finanzierung bei einer Bewertung von 5 Milliarden US-Dollar ein — nach 2,45 Milliarden im November$t$, summary = $t$Die KI-Musikplattform Suno sammelt eine Series-D-Finanzierungsrunde bei einer Bewertung von 5 Milliarden US-Dollar ein und mehr als verdoppelt damit ihre Bewertung von 2,45 Milliarden US-Dollar vom November 2025. Das Unternehmen zählt inzwischen 2 Millionen zahlende Abonnenten und erstellt täglich 7 Millionen Tracks.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'de';

UPDATE news SET title = $t$Suno привлекает раунд Series D с оценкой в $5 млрд — рост с $2,45 млрд в ноябре$t$, summary = $t$AI-платформа для создания музыки Suno привлекает раунд Series D с оценкой в $5 млрд, что более чем в два раза превышает её оценку в $2,45 млрд в ноябре 2025 года. Сейчас у компании 2 миллиона платных подписчиков, а платформа генерирует 7 миллионов треков в день.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'ru';

UPDATE news SET title = $t$Suno залучає раунд Series D за оцінкою $5 мільярдів — проти $2,45 млрд у листопаді$t$, summary = $t$AI-платформа для створення музики Suno залучає раунд Series D за оцінкою $5 мільярдів, що більш ніж удвічі перевищує її листопадову оцінку 2025 року на рівні $2,45 мільярда. Компанія має 2 мільйони платних підписників і генерує 7 мільйонів треків на день.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'ua';

UPDATE news SET title = $t$Suno מגייסת סבב Series D בשווי של 5 מיליארד דולר — עלייה מ-2.45 מיליארד דולר בנובמבר$t$, summary = $t$פלטפורמת המוזיקה מבוססת ה-AI Suno מגייסת סבב Series D בשווי של 5 מיליארד דולר, יותר מהכפלה מהשווי שלה מנובמבר 2025 שעמד על 2.45 מיליארד דולר. לחברה כיום 2 מיליון מנויים משלמים והיא מייצרת 7 מיליון רצועות ביום.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'he';

UPDATE news SET title = $t$Suno lève une série D à 5 milliards de dollars de valorisation — contre 2,45 milliards en novembre$t$, summary = $t$La plateforme musicale IA Suno est en train de lever une série D à une valorisation de 5 milliards de dollars, plus du double de sa valorisation de novembre 2025, qui était de 2,45 milliards de dollars. L'entreprise compte désormais 2 millions d'abonnés payants et génère 7 millions de morceaux par jour.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'fr';

UPDATE news SET title = $t$Suno capta Série D com valuation de US$ 5 bilhões — acima dos US$ 2,45 bi de novembro$t$, summary = $t$A plataforma de música com IA Suno está captando uma rodada Série D com valuation de US$ 5 bilhões, mais que o dobro dos US$ 2,45 bilhões alcançados em novembro de 2025. A empresa agora tem 2 milhões de assinantes pagantes e gera 7 milhões de faixas por dia.$t$
 WHERE slug = 'suno-series-d-5-billion-valuation' AND lang = 'pt';
